import numpy as np

def try_dot(expr_fn):
    try:
        with np.errstate(invalid='raise'):
            val = expr_fn()
        return {'raised': False, 'value': val}
    except FloatingPointError as e:
        return {'raised': True, 'message': str(e)}

results = {}

# 1) Plain python-list inputs
results['lists_1d_dot'] = try_dot(lambda: np.dot([1,1], [-np.inf, np.inf]))

# 2) dtype array path (a=[1,1], b=[-inf,inf])
dtypes = []
# half may be unavailable depending on build; still attempt.
for dt in [np.float16, np.float32, np.float64, np.longdouble]:
    try:
        np.dtype(dt)
        dtypes.append(dt)
    except Exception:
        pass

for dt in dtypes:
    def make_expr(dtype=dt):
        a = np.array([1,1], dtype=dtype)
        b = np.array([-np.inf, np.inf], dtype=dtype)
        return np.dot(a, b)
    results[f'dtype_array_1d_dot_{np.dtype(dt).name}'] = try_dot(make_expr)

# also do a higher-dimensional dot broadcasting variant for the same dtype set
for dt in dtypes:
    def make_expr2(dtype=dt):
        a = np.array([1,1], dtype=dtype)
        b = np.array([-np.inf, np.inf], dtype=dtype)
        # shape to force higher-dimensional dot path
        a_hd = a[np.newaxis, np.newaxis, ...]  # (1,1,2)
        b_hd = b[np.newaxis, ..., np.newaxis]  # (1,2,1)
        return np.dot(a_hd, b_hd)
    results[f'dtype_array_hd_dot_{np.dtype(dt).name}'] = try_dot(make_expr2)

probe('dot_errstate_examples', results)

